style.css:
@-moz-document url("https://actual.tepaseointenso.com"), url-prefix("https://actual.tepaseointenso.com") {
:root {
    --radius-xs: 10px;
    --radius-sm: 14px;
    --radius-md: 18px;
    --radius-lg: 22px;
    --radius-xl: 28px;

    --pad-xs: 6px;
    --pad-sm: 10px;
    --pad-md: 14px;
    --pad-lg: 18px;

    --glass: rgba(255, 255, 255, 0.08);
    --glass-strong: rgba(255, 255, 255, 0.14);
    --glass-border: rgba(255, 255, 255, 0.22);
    --shadow-lg: 0 16px 50px rgba(6, 10, 24, 0.55);

    --text: #eaf2ff;
    --muted: #b1c0df;
  }

  body {
    font-size: 14px;
    line-height: 1.35;
    letter-spacing: 0.1px;
  }

  /* Contenedores y paneles principales */
  #root,
  [role="main"],
  [role="navigation"],
  [data-testid="budget-table"],
  [data-testid="budget-table-header"] {
    border-radius: var(--radius-xl);
    background: var(--glass);
    border: 1px solid var(--glass-border);
    box-shadow: var(--shadow-lg);
    backdrop-filter: blur(18px) saturate(150%);
    -webkit-backdrop-filter: blur(18px) saturate(150%);
  }

  /* Sidebar */
  nav,
  aside,
  [data-testid="sidebar"],
  .sidebar,
  .nav,
  .menu {
    border-radius: var(--radius-xl);
    padding: var(--pad-md);
  }

  /* Filas de tabla y grupos */
  [data-testid="category-row"],
  [data-testid="category-group-row"],
  .react-aria-GridListItem {
    border-radius: var(--radius-md);
    margin: 6px 8px;
    padding: 6px 8px;
    background: rgba(255, 255, 255, 0.05);
  }

  /* Celdas y cabeceras */
  [data-testid="budget-table-header"] {
    padding: var(--pad-md) var(--pad-lg);
    border-radius: var(--radius-lg);
  }

  /* Botones y pills */
  button,
  button[data-rac],
  [role="button"] {
    border-radius: var(--radius-md);
    padding: 8px 12px;
  }

  .css-3uywls,
  .css-70zz4x,
  .css-kmyxpd {
    border-radius: var(--radius-lg);
  }

  /* Inputs */
  input,
  textarea,
  select {
    border-radius: var(--radius-sm);
    padding: 8px 10px;
  }

  /* Chips/Pills (usa variables del tema) */
  :root {
    --color-pillBackground: rgba(255, 255, 255, 0.10);
    --color-pillBackgroundLight: rgba(255, 255, 255, 0.06);
    --color-pillBorder: rgba(255, 255, 255, 0.28);
    --color-pillBorderSelected: rgba(106, 228, 255, 0.65);
    --color-pillText: var(--text);
    --color-pillTextSubdued: var(--muted);
  }

  /* Más aire en la tabla */
  [data-testid="budget-table"] .react-aria-GridListItem,
  [data-testid="budget-groups"] .react-aria-GridListItem {
    min-height: 40px;
  }

  /* Links y iconos más suaves */
  a {
    color: #8fe7ff;
  }

  svg {
    filter: drop-shadow(0 2px 4px rgba(0,0,0,0.25));
  }

  /* Scrollbar moderno */
  *::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }
  *::-webkit-scrollbar-track {
    background: rgba(255,255,255,0.04);
  }
  *::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #6ae4ff, #9a7bff);
    border-radius: 999px;
  }
}
